css:
.bct { font-size: 8px; }
.bct-grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
.bct-grid th, .bct-grid td { border: 1px solid #333; text-align: center; padding: 1px; word-wrap: break-word; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.bct-grid thead th { background: #f0f0f0; }
.bct-legend { margin-top: 8px; font-size: 8px; }
.bct-sign { width: 100%; margin-top: 16px; text-align: center; font-weight: bold; font-size: 9px; }
.bct-sign td { width: 50%; vertical-align: top; }
.bct-sign i { font-weight: normal; }
.bct-sign-space { height: 48px; }
.bct .bct-total { font-weight: 700; background: #f2f5f8; }
